  "rules": [
    {
      "rule_id": "R001",
      "rule": "Pedestrians walk at a steady, leisurely pace along paved paths.",
      "source_description_ids": [
        "D08N_08_003_C00",
        "D08N_08_005_C00"
      ]
    },
    {
      "rule_id": "R002",
      "rule": "Individuals move continuously in both directions along the walkway.",
      "source_description_ids": [
        "D08N_08_009_C00",
        "D08N_08_019_C01"
      ]
    },
    {
      "rule_id": "R003",
      "rule": "People walk in pairs or small groups without physical contact.",
      "source_description_ids": [
        "D08N_08_012_C00",
        "D08N_08_015_C00"
      ]
    },
    {
      "rule_id": "R004",
      "rule": "Pedestrians pass one another without stopping or direct interaction.",
      "source_description_ids": [
        "D08N_08_009_C01",
        "D08N_08_026_C00"
      ]
    },
    {
      "rule_id": "R005",
      "rule": "Individuals maintain safe distances from railings and water features.",
      "source_description_ids": [
        "D08N_08_003_C01",
        "D08N_08_013_C01"
      ]
    },
    {
      "rule_id": "R006",
      "rule": "Walkers carry backpacks or personal items while moving.",
      "source_description_ids": [
        "D08N_08_015_C00",
        "D08N_08_017_C00"
      ]
    },
    {
      "rule_id": "R007",
      "rule": "Some pedestrians use mobile devices while walking steadily.",
      "source_description_ids": [
        "D08N_08_015_C00",
        "D08N_08_020_C01"
      ]
    },
    {
      "rule_id": "R008",
      "rule": "People stand briefly near structures or lamp posts.",
      "source_description_ids": [
        "D08N_08_005_C01",
        "D08N_08_035_C00"
      ]
    },
    {
      "rule_id": "R009",
      "rule": "Movement is linear with no sudden stops or erratic turns.",
      "source_description_ids": [
        "D08N_08_009_C01",
        "D08N_08_018_C01"
      ]
    },
    {
      "rule_id": "R010",
      "rule": "Pedestrians navigate around fixed objects like trees and posts.",
      "source_description_ids": [
        "D08N_08_003_C00",
        "D08N_08_018_C01"
      ]
    },
    {
      "rule_id": "R011",
      "rule": "Foot traffic remains low-density and consistent throughout the scene.",
      "source_description_ids": [
        "D08N_08_009_C01",
        "D08N_08_026_C01"
      ]
    },
    {
      "rule_id": "R012",
      "rule": "Environmental elements remain static while people move through.",
      "source_description_ids": [
        "D08N_08_003_C00",
        "D08N_08_013_C01"
      ]
    }
  ]
}

